 21.195V76.631c-13.794-2.937-26.005-10.141-35.186-20.162c-15.715-9.802-27.038-25.972-30.358-44.898h-34.643v189.843c-.079 22.132-18.049 40.052-40.21 40.052c-13.058 0-24.66-6.221-32.007-15.86c-13.12-6.618-22.118-20.206-22.118-35.898c0-22.193 18-40.187 40.208-40.187c4.255 0 8.356.662 12.203 1.882v-37.822c-47.692.985-86.047 39.933-86.047 87.834c0 23.912 9.551 45.589 25.053 61.428c13.985 9.385 30.82 14.86 48.934 14.86c48.545 0 87.9-39.335 87.9-87.857z\"/><path fill=\"#00f2ea\" d=\"M242.075 76.63V66.516a66.3 66.3 0 0 1-35.186-10.047a66.47 66.47 0 0 0 35.186 20.163M176.53 11.57a68 68 0 0 1-.728-5.457V0h-47.834v189.845c-.076 22.13-18.046 40.05-40.208 40.05a40.06 40.06 0 0 1-18.09-4.287c7.347 9.637 18.949 15.857 32.007 15.857c22.16 0 40.132-17.918 40.21-40.05V11.571zM99.966 113.58v-10.769a89 89 0 0 0-12.061-.818C39.355 101.993 0 141.327 0 189.845c0 30.419 15.467 57.227 38.971 72.996c-15.502-15.838-25.053-37.516-25.053-61.427c0-47.9 38.354-86.848 86.048-87.833\"/>"},"si:x:#ececec":{"vb":"0 0 24 24","body":"<path fill=\"#ececec\" d=\"M14.234 10.162L22.977 0h-2.072l-7.591 8.824L7.251 0H.258l9.168 13.343L.258 24H2.33l8.016-9.318L16.749 24h6.993zm-2.837 3.299l-.929-1.329L3.076 1.56h3.182l5.965 8.532l.929 1.329l7.754 11.09h-3.182z\"/>"}};

  const esc = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  function keyFor(n) {
    const k = (n || '').toLowerCase();
    for (const [kw, key] of MAP) {
      if (new RegExp('(^|[^a-z0-9])' + esc(kw) + '($|[^a-z0-9])').test(k)) return key;
    }
    return null;
  }
  const key = $derived(keyFor(name));
  const logo = $derived(key ? LOGOS[key] : null);
  const letter = $derived((name || '?').trim().charAt(0).toUpperCase() || '?');
  // Cada logo pinta con sus propios ids: si dos comparten el de un degradado o una máscara y el
  // primero vive en una parte oculta (la barra lateral en el móvil), el segundo sale sin forma.
  const uid = 'b' + Math.random().toString(36).slice(2, 8);
  const body = $derived(logo ? logo.body
    .replace(/id="([^"]+)"/g, (_, id) => 'id="' + id + '-' + uid + '"')
    .replace(/url\(#([^)]+)\)/g, (_, id) => 'url(#' + id + '-' + uid + ')')
    .replace(/href="#([^"]+)"/g, (_, id) => 'href="#' + id + '-' + uid + '"') : '');
</script>

{#if logo}
  <svg class="brandlogo" width={size} height={size} viewBox={logo.vb} preserveAspectRatio="xMidYMid meet" role="img" aria-label={name}>{@html body}</svg>
{:else}
  <span class="brandlogo brandlogo--mono" aria-label={name} title={name}
    style={`width:${size}px;height:${size}px;font-size:${Math.max(9, Math.round(size * 0.5))}px;background:${entityColor(null, name)}`}>{letter}</span>
{/if}

<style>
  .brandlogo { flex: 0 0 auto; display: inline-block; }
  .brandlogo--mono {
    display: inline-flex; align-items: center; justify-content: center;
    border-radius: 5px; color: #fff; font-family: var(--font-display); font-weight: 700; line-height: 1;
    user-select: none;
  }
</style>
